PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,name TEXT NOT NULL,place TEXT NOT NULL,kind TEXT NOT NULL,time TEXT NOT NULL,lat REAL NOT NULL,lon REAL NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,tenant TEXT NOT NULL,owner TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS edges(source TEXT NOT NULL,relation TEXT NOT NULL,target TEXT NOT NULL REFERENCES events(id),PRIMARY KEY(source,relation,target));
CREATE TABLE IF NOT EXISTS outbox(seq INTEGER PRIMARY KEY,entity TEXT NOT NULL REFERENCES events(id),status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,entity TEXT NOT NULL REFERENCES events(id),new_time TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(key TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS model_usage(id INTEGER PRIMARY KEY,requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ui_proposals(id TEXT PRIMARY KEY,session_hash TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,entity_version INTEGER NOT NULL,expires_at INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences(entity TEXT NOT NULL,kind TEXT NOT NULL,value TEXT NOT NULL CHECK(value IN ('0','1')),PRIMARY KEY(entity,kind));
CREATE TABLE IF NOT EXISTS history(seq INTEGER PRIMARY KEY,entity TEXT NOT NULL REFERENCES events(id),old_time TEXT NOT NULL,old_version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY,action TEXT NOT NULL,entity TEXT NOT NULL,prev TEXT NOT NULL,hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
